import {spawn} from 'node:child_process';import path from 'node:path';import fs from 'node:fs/promises';
const scripts=['poc:01','poc:02','poc:03','poc:04','poc:05'];const results=[];
for(const script of scripts){const r=await new Promise<{script:string,code:number,stdout:string,stderr:string}>(resolve=>{const c=spawn(process.platform==='win32'?'npm.cmd':'npm',['run','--silent',script],{env:process.env});let stdout='',stderr='';c.stdout.on('data',d=>stdout+=d);c.stderr.on('data',d=>stderr+=d);c.on('close',code=>resolve({script,code:code??1,stdout,stderr}));});results.push(r);console.log(`\n=== ${script} (${r.code}) ===\n${r.stdout}${r.stderr}`);}await fs.mkdir('reports',{recursive:true});await fs.writeFile(path.join('reports','run-all.json'),JSON.stringify(results,null,2));if(results.some(r=>r.code!==0))process.exitCode=1;

